# Fix: Start with all-background, only place shifted pixels

def shift_down_correct(grid, amount=1, fg_val=0, bg_val=0):
    rows = len(grid)
    cols = len(grid[0]) if grid else 0

    # Start with a fresh background grid (fill with bg_val)
    new_grid = [[bg_val for _ in range(cols)] for _ in range(rows)]

    # Place foreground pixels shifted down
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == fg_val:
                new_r = r + amount
                if new_r < rows:
                    new_grid[new_r][c] = fg_val

    return new_grid

output = shift_down_correct(grid, bg_val=3, fg_val=0)

print("Correctly transformed grid:")
for row in output:
    print(row)
